//! Sound effects. Gameplay code queues `Sound`s; playback exists only in the
//! WASM build (Bevy audio needs ALSA to compile natively, and the browser is
//! the product). Sounds are generated by `examples/make_sfx.rs` (original).
//! Mute is remembered in `localStorage`.

use bevy::prelude::*;

use crate::config;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Sound {
    Deploy,
    Melee,
    Shot,
    Cannon,
    Heal,
    Evolve,
    Synergy,
    StrongholdHit,
    Victory,
    Defeat,
    Click,
}

#[cfg_attr(not(target_arch = "wasm32"), allow(dead_code))] // played only on the web
pub const SOUNDS: [(Sound, &str); 11] = [
    (Sound::Deploy, "deploy"),
    (Sound::Melee, "melee"),
    (Sound::Shot, "shot"),
    (Sound::Cannon, "cannon"),
    (Sound::Heal, "heal"),
    (Sound::Evolve, "evolve"),
    (Sound::Synergy, "synergy"),
    (Sound::StrongholdHit, "stronghold_hit"),
    (Sound::Victory, "victory"),
    (Sound::Defeat, "defeat"),
    (Sound::Click, "click"),
];

/// Minimum seconds between two plays of the same sound (combat spam).
const THROTTLE: f64 = 0.09;

#[derive(Resource, Default)]
pub struct Sounds {
    queue: Vec<Sound>,
    last: Vec<(Sound, f64)>,
    pub muted: bool,
}

impl Sounds {
    pub fn play(&mut self, s: Sound) {
        if !self.muted && !self.queue.contains(&s) {
            self.queue.push(s);
        }
    }

    pub fn toggle_mute(&mut self) {
        self.muted = !self.muted;
        config::save_flag("tbg_muted", self.muted);
    }

    /// Sounds due now, honoring the per-sound throttle.
    fn drain(&mut self, now: f64) -> Vec<Sound> {
        let mut out = Vec::new();
        for s in std::mem::take(&mut self.queue) {
            let recent = self.last.iter().any(|(l, t)| *l == s && now - t < THROTTLE);
            if !recent {
                self.last.retain(|(l, _)| *l != s);
                self.last.push((s, now));
                out.push(s);
            }
        }
        out
    }
}

pub fn plugin(app: &mut App) {
    let muted = config::load_flag("tbg_muted");
    app.insert_resource(Sounds { muted, ..default() });
    #[cfg(target_arch = "wasm32")]
    app.add_systems(Startup, web::load)
        .add_systems(Update, web::play);
    #[cfg(not(target_arch = "wasm32"))]
    app.add_systems(Update, |time: Res<Time>, mut s: ResMut<Sounds>| {
        s.drain(time.elapsed_secs_f64());
    });
}

#[cfg(target_arch = "wasm32")]
mod web {
    use bevy::prelude::*;

    use super::{Sound, Sounds, SOUNDS};

    #[derive(Resource)]
    pub(super) struct Clips(Vec<(Sound, Handle<AudioSource>)>);

    pub(super) fn load(mut commands: Commands, assets: Res<AssetServer>) {
        let clips = SOUNDS
            .iter()
            .map(|(s, name)| (*s, assets.load(format!("audio/{name}.wav"))))
            .collect();
        commands.insert_resource(Clips(clips));
    }

    pub(super) fn play(
        mut commands: Commands,
        time: Res<Time>,
        mut sounds: ResMut<Sounds>,
        clips: Res<Clips>,
    ) {
        for s in sounds.drain(time.elapsed_secs_f64()) {
            if let Some((_, h)) = clips.0.iter().find(|(c, _)| *c == s) {
                commands.spawn((AudioPlayer::new(h.clone()), PlaybackSettings::DESPAWN));
            }
        }
    }
}
